<?php
require_once 'functions.php';$products=$pdo->query('SELECT id,name,category,description,selling_price,unit,image_url FROM products ORDER BY category,name')->fetchAll();$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']);$phone=trim($_POST['phone']);$notes=trim($_POST['notes']);$pid=(int)$_POST['product_id'];$qty=(float)$_POST['quantity'];
 if($name&&$phone&&$qty>0){$pdo->beginTransaction();$pdo->prepare('INSERT INTO customer_orders(customer_name,phone,notes) VALUES(?,?,?)')->execute([$name,$phone,$notes]);$oid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO order_items(order_id,product_id,quantity,requested_measurements) VALUES(?,?,?,?)')->execute([$oid,$pid,$qty,trim($_POST['measurements'])]);$pdo->commit();notify_owners($pdo,"New customer order #$oid from $name ($phone)");$message="Your order request has been received. Reference #$oid.";}else{$message='Please complete all required fields.';}}
page_header('Place an order');?><div class="hero"><div><p class="eyebrow">CUSTOMER PORTAL</p><h1>Browse glass products</h1><p>Send an order request. The shop will contact you to confirm availability and pricing.</p></div></div><?php if($message):?><p class="success"><?=h($message)?></p><?php endif;?>
<section class="products"><?php foreach($products as $p):?><article class="product"><?php if($p['image_url']):?><img src="<?=h($p['image_url'])?>" alt="<?=h($p['name'])?>"><?php else:?><div class="placeholder">GLASS</div><?php endif;?><div class="pad"><small><?=h($p['category'])?></small><h3><?=h($p['name'])?></h3><p><?=h($p['description'])?></p><strong>KSh <?=number_format($p['selling_price'],2)?> / <?=h($p['unit'])?></strong></div></article><?php endforeach;?></section>
<section class="panel narrow"><h2>Submit order request</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Your name<input name="name" required></label><label>Phone number<input name="phone" required></label><label>Product<select name="product_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=h($p['name'])?></option><?php endforeach;?></select></label><label>Quantity<input type="number" name="quantity" step="0.01" min="0.01" required></label><label>Measurements (if applicable)<input name="measurements" placeholder="e.g. 1200mm × 900mm"></label><label>Additional details<textarea name="notes"></textarea></label><button>Submit order</button></form></section><?php page_footer();?>
